INSERT INTO `products` VALUES (397,1,'new product','Step into timeless elegance with this handcrafted Kota Doria saree, designed for subtle sophistication and all-day comfort. Woven on an airy, breathable base in a soft blush peach tone, the saree features an intricate garden-inspired floral pattern set within delicate geometric panels.   The pallu is accentuated with striking silver zari chevron (leheriya) patterns and floral medallion roundels that catch the light effortlessly. It comes paired with an unstitched contrast deep wine/maroon blouse piece detailed with silver zari borders, creating a striking traditional balance. Perfect for day weddings, festive poojas, and celebratory gatherings',NULL,NULL,44000.00,1,'https://ik.imagekit.io/5gma4ap5d/arzoo-saree/products/1793087697836-image2_e796aEV5f.jpeg',0,'2026-10-26 11:33:46',NULL,NULL,'pink',NULL,'flolar',NULL,NULL,NULL,'use Silver AND Gold','have it',NULL,'Kaithoon,kota','70%cotten and 30% silk','gold single tissue','500gm','38 inche','Royal Heritage',NULL,NULL,40000.00,130.00,2,45000.00,2,0,NULL,NULL,NULL,'https://ik.imagekit.io/5gma4ap5d/arzoo-saree/products/1793087699441-productvisoe_oVnonuSik.mp4','6 meter','[1, 3]'),(398,1,'new2 product','Apni ethnic wardrobe mein shamil karein yeh khubsurat handloom Kota Doria saree, jo ek serene lavender (halka jamuni) shade mein aati hai. Iska lightweight aur breathable fabric poore din aaram aur elegance deta hai. Saree par poori body mein naazuk floral buttis bani hui hain, jo iske look ko aur bhi graceful banati hain.\r\n\r\nIs saree ki sabse badi khasiyat iske rich contrasting magenta aur red borders hain, jinme classic chevron (leheriya) patterns aur fine zari lines di gayi hain. Iske sath ek contrast rich red unstitched blouse piece milta hai, jo iske traditional look ko mukammal karta hai. Yeh festive celebrations, poojas, aur elegant daytime events ke liye ek perfect choice hai.',NULL,NULL,11000.00,1,'https://ik.imagekit.io/5gma4ap5d/arzoo-saree/products/1793016416751-image_kw6Vy7W-R.jpeg',0,'2026-10-26 12:06:59',NULL,NULL,'purple','red','simple kota doriya',NULL,NULL,NULL,'use Silver','have',NULL,'Kaithoon,kota,rajsthaan','70% cotton and 30% silk',NULL,'350gm','38 inche','Amir',NULL,NULL,9000.00,100.00,2,NULL,0,0,NULL,NULL,NULL,NULL,'6 meter','[1, 2]'),(399,1,'Handcrafted Vibrant Orange and Yellow Kota Doria Saree with Silver Zari Weaving','Embrace timeless elegance with this stunning, handcrafted Kota Doria saree featuring a striking blend of vibrant orange and contrasting yellow borders. Celebrated for its signature checkered khat weave and feather-light feel, this piece is an exquisite masterpiece designed for festive occasions, weddings, and traditional celebrations.',NULL,NULL,26000.00,1,'https://ik.imagekit.io/5gma4ap5d/arzoo-saree/products/1793088880611-image7_4Qni0ngmU.jpeg',0,'2026-10-27 08:14:43',NULL,NULL,'orange',NULL,'Silver zari border',NULL,'Lehriya design',NULL,'SIlver and Gold','yellow',NULL,'Kaithoon,kota','70% cotten and silk 30%','cotten and silk khats','375gm','38 inche','Royal Heritage',NULL,NULL,23000.00,130.00,2,NULL,0,0,NULL,NULL,'1',NULL,'6 Meter','[1, 3]'),(400,1,'Handcrafted Off-White & Pink Kota Doria Saree with Silver-Gold Zari Floral Motifs','Exude grace and sophistication with this refreshing pastel green handloom Kota Doria saree. Known for its feather-light feel and signature checkered khat weave, this exquisite piece features graceful fan-shaped botanical motifs and elegant silver zari detailing, making it an ideal choice for graceful daytime events, festive gatherings, and traditional occasions.',NULL,NULL,30000.00,3,'https://ik.imagekit.io/5gma4ap5d/arzoo-saree/products/1793089943693-image16_vgyRIyS-Ui.jpeg',0,'2026-10-27 08:32:26',NULL,NULL,'off white','pink','silverwork kanchi border','thread work','silver and gold butaa`s',NULL,'Silver and gold','off white',NULL,'Kaithoon, Kota, Rajasthan','70% cotten and silk 30%',NULL,'400gm','38 inche','Royal Heritage',NULL,NULL,26000.00,130.00,2,NULL,0,0,NULL,NULL,NULL,NULL,'6 meter','[4, 3, 1]'),(401,1,'Handcrafted Cream & Brown Kota Doria Saree with Multi-Color Floral Bootis and Silver Zari Weaving','Add a touch of vibrant charm to your ethnic wardrobe with this cream handloom Kota Doria saree. Beautifully accented with contrasting brown borders and playful multi-colored floral bootis (red, yellow, and brown) set against a delicate silver zari checkered lattice, this saree is lightweight, breathable, and perfect for casual outings, family gatherings, and daytime celebrations.',NULL,NULL,29000.00,1,'https://ik.imagekit.io/5gma4ap5d/arzoo-saree/products/1793090747681-image19_uswZaIbVy.jpeg',0,'2026-10-27 08:45:50',NULL,NULL,'Dark cream',NULL,'simple siver border','flolar silver check ','checks and flowers',NULL,'Silver','dark brown blouse and butis design',NULL,'Kaithoon, Kota, Rajasthan','70%cotten and 30% silk','cotten and silk','400gm','38 inche','Royal Heritage',NULL,NULL,26000.00,130.00,2,NULL,0,0,NULL,NULL,NULL,NULL,'6 Meter','[4, 3, 1]'),(402,1,'Handcrafted Beige & Dark Brown Kota Doria Saree with Pichwai-Inspired Cow & Lotus Motifs','Celebrate rich heritage and traditional artistry with this elegant beige handloom Kota Doria saree. Beautifully adorned with Pichwai-inspired motifs of sacred cows and lotus flowers in vibrant tones of white, pink, and gold, alongside a rich dark brown border, this lightweight masterpiece is a timeless choice for cultural events, festive occasions, and traditional gatherings',NULL,NULL,16500.00,1,'https://ik.imagekit.io/5gma4ap5d/arzoo-saree/products/1793091335250-image22_m-G1XV_wB.jpeg',0,'2026-10-27 08:55:37',NULL,NULL,'cream',NULL,'thread border',NULL,' cow and flolar butaa`s',NULL,'silver','dark brown with deer design',NULL,'Kaithoon, Kota, Rajasthan','70%cotten and 30%silk',NULL,'350gm','38 inche','Royal Heritage',NULL,NULL,13500.00,130.00,2,NULL,0,0,NULL,NULL,NULL,NULL,'6 Meter','[2, 4]'),(403,1,'Handcrafted Magenta Pink Kota Doria Saree with Vibrant Floral Bootis and Silver Zari Brocade Pallu','Make a vibrant statement with this striking magenta pink handloom Kota Doria saree. Featuring stunning, colorful floral bunch motifs scattered across the body and an opulent broad silver zari brocade pallu, this lightweight and breezy masterpiece is a splendid choice for weddings, festive occasions, and vibrant celebrations.',NULL,NULL,12500.00,1,'https://ik.imagekit.io/5gma4ap5d/arzoo-saree/products/1793092004469-image25_JBlTdlmS9.jpeg',0,'2026-10-27 09:06:50',NULL,NULL,'pink',NULL,'kataan and zari border',NULL,'butaa`s',NULL,'silver','pink',NULL,'Kaithoon, Kota, Rajasthan','70%cotten and 30%silk',NULL,'350gm','38 inche','Royal Heritage',NULL,NULL,10200.00,150.00,2,NULL,0,0,NULL,NULL,NULL,'https://ik.imagekit.io/5gma4ap5d/arzoo-saree/products/1793092005677-productvidoe1_3KK4-rlR8.mp4','6 meter','[2, 4]'),(404,1,'Handcrafted Sky Blue & Pink Kota Doria Saree with Silver Zari Lattice and Floral Bootis','Elevate your ethnic collection with this graceful sky blue handloom Kota Doria saree. Featuring a delicate silver zari diamond lattice woven across the body, accented with vibrant multi-colored floral bootis (blue, yellow, and pink), and finished with a striking pink and silver zari border, this lightweight masterpiece is perfect for festive wear, family gatherings, and elegant daytime events.',NULL,NULL,30000.00,1,'https://ik.imagekit.io/5gma4ap5d/arzoo-saree/products/1793092615189-image29_vkOADAUxZ.jpeg',0,'2026-10-27 09:16:57',NULL,NULL,'ligth blue',NULL,'silver big border',NULL,'all over zaal',NULL,'pure silver','pink',NULL,'Kaithoon, Kota, Rajasthan','70%cotten and 30%silk',NULL,'350gm','38 inche','Royal Heritage',NULL,NULL,26000.00,130.00,2,NULL,0,0,NULL,NULL,NULL,NULL,'6 meter','[4, 3, 5]'),(405,1,'Handcrafted Lavender Kota Doria Saree with Diamond Buttas and Peacock Pallu','Embrace graceful elegance with this gorgeous lavender handloom Kota Doria saree. Beautifully patterned across the body with geometric diamond buttas and delicate zari accents, and paired with a magnificent peacock-motif pallu and rich purple borders, this lightweight and airy masterpiece is ideal for festive occasions, weddings, and traditional gatherings.',NULL,NULL,13000.00,3,'https://ik.imagekit.io/5gma4ap5d/arzoo-saree/products/1793093051257-image31_jkp_9Zm1q.jpeg',0,'2026-10-27 09:24:13',NULL,NULL,'purple',NULL,'simple thread border',NULL,'bootaa`s',NULL,'pure silver','running',NULL,'Kaithoon, Kota, Rajasthan','70%cotten and 30% silk',NULL,'350gm','80 inche','Royal Heritage',NULL,NULL,11000.00,130.00,2,NULL,0,0,NULL,NULL,NULL,NULL,'6 meter','[2, 4]'),(406,1,'Handcrafted Orange & Yellow Kota Doria Saree with Pichwai Cow-Lotus Motifs and Silver Zari Brocade Pallu','Celebrate rich Indian heritage with this vibrant orange handloom Kota Doria saree. Beautifully designed with traditional Pichwai-inspired motifs of sacred cows and lotus blooms woven into striking yellow borders, alongside an opulent silver zari brocade pallu, this lightweight and airy masterpiece is a splendid choice for weddings, cultural festivals, and traditional celebrations.',NULL,NULL,20000.00,1,'https://ik.imagekit.io/5gma4ap5d/arzoo-saree/products/1793093621295-image36_pepdvso7D.jpeg',0,'2026-10-27 09:33:43',NULL,NULL,'orange','yellow','cow and animal and floral bootaa`s',NULL,'birds design',NULL,'pure silver and gold zari','simple yellow',NULL,'kaithoon,kota','70%cotten and 30% silk',NULL,'350gm','38 inche','Royal Heritage',NULL,NULL,16000.00,130.00,2,NULL,0,0,NULL,NULL,NULL,NULL,'6meter','[2, 4, 5]'),(407,1,'Handcrafted Bright Yellow & Orange Kota Doria Saree with Floral Bootis and Parrot-Botanical Pallu','Handcrafted Bright Yellow & Orange Kota Doria Saree with Floral Bootis and Parrot-Botanical PalluBrighten up your celebrations with this cheerful yellow handloom Kota Doria saree. Featuring neat floral bootis scattered across the body and an exquisite broad pallu intricately woven with blooming botanical branches and colorful parrots, this lightweight and airy masterpiece is a splendid choice for haldi ceremonies, festive daytime wear, and traditional gatherings.',NULL,NULL,13000.00,1,'https://ik.imagekit.io/5gma4ap5d/arzoo-saree/products/1793094388823-image38_COmoxhHcb.jpeg',1,'2026-10-27 09:46:31',NULL,NULL,'yellow',NULL,' simple silver zari thread',NULL,'flolar flower',NULL,'pure silver','simple orange with silver ',NULL,'kaithoon, kota','70% cotten and 30% silk',NULL,'350gm','38 inche','Royal Heritage',NULL,NULL,10000.00,130.00,2,NULL,0,0,NULL,NULL,NULL,NULL,'6 meter','[2, 4, 5]'),(408,1,'Handcrafted Navy Blue Kota Doria Saree with Blooming Lotus Vines and Polka Dots','Exude timeless elegance with this deep navy blue handloom Kota Doria saree. Beautifully detailed with climbing floral vines, blooming multi-colored lotus motifs, and delicate white polka dots scattered across the body, this lightweight and airy masterpiece offers a sophisticated look for evening events, festive gatherings, and formal ethnic occasions.',NULL,NULL,9000.00,1,'https://ik.imagekit.io/5gma4ap5d/arzoo-saree/products/1793094947406-image39_NltMgD7fd.jpeg',0,'2026-10-27 09:55:50',NULL,NULL,'navy dark blue',NULL,'simpel thread border',NULL,'mix color flowers',NULL,'pure silver',NULL,NULL,'Kaithoon,kota','70%cotten and 30% silk',NULL,'350gm','38inche','Royal Heritage',NULL,NULL,7000.00,130.00,2,NULL,0,0,NULL,NULL,NULL,NULL,'5 meter','[2, 3]'),(409,1,'Handcrafted Rich Magenta Kanjeevaram-Style Silk Saree with All-Over Zari Brocade and Floral Borders','Make a breathtaking statement at weddings, grand celebrations, and festive events with this opulent magenta pink handloom saree. Fully blanketed in intricate gold zari geometric and floral brocade patterns across the entire body, and framed by vibrant floral-woven borders, this heavy yet graceful masterpiece exudes timeless royal elegance.',NULL,NULL,55000.00,0,'https://ik.imagekit.io/5gma4ap5d/arzoo-saree/products/1793095544320-image43_pGbdUNGqj.jpeg',0,'2026-10-27 10:05:46',NULL,N